import {getConfig} from './httpClient';
//createReceiptServices
export const createReceiptServices = (fetchRequest: any) => ({
  async getReceipt(page: number, size: number, body?: any) {
    const endPoint = `/services/thads-bldt/api/search/electronic-receipts?page=${page}&size=${size}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body) || '{}',
      });
      const totalData = data?.headers.get('x-total-count') || 0;
      return Promise.resolve({
        data: data?.data,
        totalData: totalData,
      });
    } catch (error) {
      Promise.reject(error);
    }
  },
});
