import {useCallback, useState} from 'react';
import {ActivityIndicator, View} from 'react-native';
import TextCM from '../../components/Text';
import {useFocusEffect, useNavigation} from '@react-navigation/native';
import {Color, NavigationName} from '../../../constants';
import {Icon, List, ListItem} from '@ui-kitten/components';
import {useTicketServices} from '../../../hooks/apiHooks/useAPI';
import {IServicesHome, Modeler} from './helper';

type Props = {
  onClose: () => void;
};

const CreateNewScreen = ({onClose}: Props) => {
  const navigation = useNavigation<any>();
  const [listServices, setListServices] = useState<IServicesHome[]>([]);

  const [loading, setLoading] = useState(true);
  const TicketService = useTicketServices();

  const getServiceOfTHADS = async () => {
    try {
      setLoading(true);
      const body = {
        serviceCode: 'BIENLAITHADS',
        textSearch: '',
        roleIds: '',
      };
      const params = {
        page: 0,
        size: 1000000,
      };
      const dataResp = await TicketService.getListServives(body, params);
      if (dataResp) {
        setListServices(dataResp.content);
      }
      return dataResp;
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  useFocusEffect(
    useCallback(() => {
      getServiceOfTHADS();
    }, []),
  );
  const handleCreate = (item: Modeler) => {
    onClose();
    navigation.navigate(NavigationName.CreateTicketScreen, {
      dataTicket: item,
    });
  };
  return (
    <>
      {!loading ? (
        <List
          data={listServices?.[0]?.modelers}
          renderItem={({item}) => (
            <ListItem
              title={item.flowName}
              onPress={() => handleCreate(item)}
              accessoryRight={
                <Icon
                  name="arrow-ios-forward-outline"
                  fill="#1D2939"
                  width={20}
                  height={20}
                />
              }
            />
          )}
          keyExtractor={(item, index) => index.toString()}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                height: 200,
              }}>
              <TextCM>Không có dữ liệu</TextCM>
            </View>
          )}
        />
      ) : (
        <ActivityIndicator size="small" color={Color.BgPrimary} />
      )}
    </>
  );
};

export default CreateNewScreen;
