import {StyleSheet, Text, TouchableOpacity, View} from 'react-native';
import {useState} from 'react';
import {Icon} from '@ui-kitten/components';

import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../../../../constants';
import ExpandIssueReceipt from '../expand-issue-receipt';

type Props = {
  item: any;
};

const IssueReceiptItem = ({item}: Props) => {
  const {t} = useTranslation();

  const [isExpand, setIsExpand] = useState(false);
  const toggleExpand = () => setIsExpand(!isExpand);
  const [openModalTrash, setOpenModalTrash] = useState(false);
  const handleDeleteAttach = () => {
    console.log('Xoá tệp đính kèm');
  };
  return (
    <View key={item.id}>
      <TouchableOpacity
        style={styles.documentItem}
        onPress={() => toggleExpand()}>
        <View style={styles.documentRow}>
          <View style={styles.iconTitleContainer}>
            <View style={styles.iconContainer}>
              <Icon
                name={isExpand ? 'chevron-down' : 'chevron-right'}
                fill={'#C83A1B'}
                width={12}
                height={12}
              />
            </View>
            <Text style={styles.documentTitle}>{item.title}</Text>
          </View>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandIssueReceipt item={item} />}

      <ModalConfirmCM
        type="delete"
        title={'Xoá tài liệu'}
        content={'Bạn có muốn xoá tài liệu đính kèm trên biên lai'}
        onClose={() => setOpenModalTrash(false)}
        isVisible={openModalTrash}
        labelCancel={t('CM.back')}
        labelConfirm={t('CM.confirm')}
        onConfirm={handleDeleteAttach}
      />
    </View>
  );
};
export default IssueReceiptItem;

const styles = StyleSheet.create({
  documentItem: {
    paddingVertical: 12,
  },
  documentRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  iconTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
    columnGap: 8,
  },
  iconContainer: {
    borderWidth: 1,
    width: 14,
    height: 14,
    borderColor: '#C83A1B',
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
  },
  documentTitle: {
    fontSize: 13,
    fontFamily: Font.InterMedium500,
    color: '#00204DE5',
    flex: 1,
  },
  trashIcon: {
    padding: 4,
  },
});
