import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {TouchableOpacity, View} from 'react-native';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../../../../components/Text';

type ItemType = {
  title: string;
  value: number;
  bgColor: string;
  textColor: string;
};

const OverviewDocument = () => {
  const navigation = useNavigation<any>();
  const {t} = useTranslation();

  const data = [
    {
      title: 'Chờ xử lý',
      value: 100,
      bgColor: '#ECEFFE',
      textColor: '#0673C6',
    },
    {
      title: 'Chờ phản hồi',
      value: 1000,
      bgColor: '#FEF4E6',
      textColor: '#E18308',
    },
    {
      title: 'Sắp hết hạn',
      value: 200,
      bgColor: '#FEECEB',
      textColor: '#DA3E33',
    },
  ];

  const renderItem = (item: ItemType) => {
    return (
      <TouchableOpacity
        onPress={() => {
          onPressItem(item);
        }}
        key={item.title}
        style={[
          styles.viewItem,
          {
            backgroundColor: item.bgColor,
          },
        ]}>
        <TextCM
          style={[
            styles.txtValue,
            {
              color: item.textColor,
            },
          ]}>
          {formatNumber(item.value)}
        </TextCM>
        <TextCM
          style={[
            styles.txtName,
            {
              color: item.textColor,
            },
          ]}>
          {item.title}
        </TextCM>
      </TouchableOpacity>
    );
  };

  const onPressItem = (item: ItemType) => {
    switch (item.title) {
      case t('HM.TxtPending'):
        break;
      case t('HM.TxtWaitingResponse'):
        break;
      case t('HM.TxtExpire'):
        break;
    }
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{'Tổng quan biên lai'}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default OverviewDocument;
