import {Icon} from '@ui-kitten/components';
import {Text, TouchableOpacity, View} from 'react-native';
import {styles} from './styles';
import {TransactionItem} from '../..';
import {useState} from 'react';
import ExpandTransfer from '../expand-transfer';

const ItemTransferReceipt = ({item}: {item: TransactionItem}) => {
  const [isExpand, setIsExpand] = useState(false);

  const toggleExpand = () => {
    setIsExpand(!isExpand);
  };
  return (
    <>
      <TouchableOpacity style={styles.itemContainer} onPress={toggleExpand}>
        <View style={styles.wrapLabel}>
          <View style={styles.iconContainer}>
            <Icon
              name={isExpand ? 'chevron-down' : 'chevron-right'}
              fill={'#C83A1B'}
              width={12}
              height={12}
            />
          </View>
          <Text style={styles.itemLabel}>Tên biên lai</Text>
        </View>
        <View style={styles.wrapValue}>
          <Text style={styles.itemDetails}>{item.details}</Text>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandTransfer />}
    </>
  );
};

export default ItemTransferReceipt;
