import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {View} from 'react-native';
import TextCM from '../../../../components/Text';
import {IconRoundDocument, IconRoundUser} from '../../../../../assets/images';

type DataType = {
  title: string;
  value: number;
  icon: React.ReactNode;
};

const Statistical = () => {
  const {t} = useTranslation();

  const data: DataType[] = [
    {
      title: 'Số biên lai chưa hoàn thành',
      value: 100,
      icon: <IconRoundDocument width={48} height={48} />,
    },
    {
      title: '---',
      value: 20,
      icon: <IconRoundUser width={48} height={48} />,
    },
    {
      title: '---',
      value: 2000,
      icon: <IconRoundUser width={48} height={48} />,
    },
  ];

  const renderItem = (item: DataType) => {
    return (
      <View style={styles.viewItem} key={item.title}>
        {item.icon}
        <View>
          <TextCM style={styles.txtValue}>{formatNumber(item.value)}</TextCM>
          <TextCM style={styles.txtName}>{item.title}</TextCM>
        </View>
      </View>
    );
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{'Thống kê'}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default Statistical;
