import {Icon, IndexPath} from '@ui-kitten/components';
import React, {useState} from 'react';
import {Text, TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import InputDate from './InputDate';
import {
  listDayValue,
  listPayment,
  listStatusReceipt,
  listTypeReceipt,
} from './helper';
import {useReceiptZustandStore} from '../../store/myReceiptZustandStore';
import Toast from 'react-native-toast-message';
type Props = {
  onClose: () => void;
};
const ModalFilter = ({onClose}: Props) => {
  const {t} = useTranslation();
  const {valueFilterSearch, setValueFilterSearch} = useReceiptZustandStore();
  const [dayValue, setDayValue] = useState<IndexPath>();
  const setDefault = () => {
    setValueFilterSearch({
      rangeDay: {startDate: new Date(), endDate: new Date()},
    });
  };
  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Ngày bắt đầu không được lớn hơn ngày kết thúc.',
      });
      return;
    }

    setValueFilterSearch({
      ...valueFilterSearch,
      rangeDay: {
        ...valueFilterSearch.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const newEnd = value ? new Date(value) : undefined;
    if (newEnd && newEnd > today) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: 'Ngày kết thúc không được lớn hơn ngày hôm nay.',
      });
      return;
    }
    const {startDate} = valueFilterSearch.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: 'Ngày kết thúc không được nhỏ hơn ngày bắt đầu.',
      });
      return;
    }
    setValueFilterSearch({
      ...valueFilterSearch,
      rangeDay: {...valueFilterSearch.rangeDay, endDate: newEnd},
    });
  };
  return (
    <View style={{backgroundColor: '#fff'}}>
      <View style={{marginVertical: 4}}>
        <Text
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Loại biên lai
        </Text>
        <DropdownListCM
          onSelect={(item: IndexPath) => {
            setValueFilterSearch({...valueFilterSearch, typeReceipt: item});
          }}
          valueSelect={valueFilterSearch.typeReceipt}
          placeholder={'Chọn loại biên lai'}
          multiple={false}
          listData={listTypeReceipt}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <Text
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Hình thức nộp tiền
        </Text>
        <DropdownListCM
          onSelect={(item: IndexPath) => {
            setValueFilterSearch({...valueFilterSearch, paymentMethod: item});
          }}
          valueSelect={valueFilterSearch.paymentMethod}
          placeholder={'Chọn hình thức nộp tiền'}
          multiple={false}
          listData={listPayment}
        />
      </View>
      <View style={{marginVertical: 4}}>
        <Text
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Trạng thái biên lai
        </Text>
        <DropdownListCM
          onSelect={(item: IndexPath) => {
            setValueFilterSearch({...valueFilterSearch, receiptStatus: item});
          }}
          valueSelect={valueFilterSearch.receiptStatus}
          placeholder={'Chọn trạng thái'}
          multiple={true}
          listData={listStatusReceipt}
        />
      </View>
      <View style={{marginVertical: 4, marginBottom: 12}}>
        <Text
          style={{
            marginVertical: 8,
            fontFamily: Font.InterMedium500,
            fontSize: 14,
          }}>
          Lọc theo ngày tạo
        </Text>
        {valueFilterSearch.isCustomDay || true ? (
          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginTop: 10,
              columnGap: 8,
            }}>
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearch?.rangeDay?.startDate || new Date()}
              onChangeDate={value => {
                onChangeStartDate(value);
              }}
              disabled={false}
            />
            <Icon name="arrow-forward-outline" width={20} height={20} />
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearch?.rangeDay?.endDate || new Date()}
              onChangeDate={value => {
                onChangeEndDate(value);
              }}
              disabled={false}
            />
          </View>
        ) : (
          <DropdownListCM
            onSelect={(val: IndexPath) => {
              setDayValue(val);
              if (listDayValue[val.row].value === 'Custom') {
                setValueFilterSearch({...valueFilterSearch, isCustomDay: true});
              }
            }}
            valueSelect={dayValue}
            placeholder={'Thời gian lọc'}
            multiple={false}
            listData={listDayValue}
          />
        )}
      </View>
      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
        }}>
        <TouchableOpacity
          onPress={setDefault}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#FBEFEA',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#C83A1B', textAlign: 'center'}}>
            {t('DB.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={onClose}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#C83A1B',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>Lọc</TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
