import {getConfig} from './httpClient';

export const createTicketServices = (fetchRequest: any) => ({
  async getListServives(body: any, params: any) {
    const endPoint = `/services/erequest/api/work-flows/search?sort=displayOrder,asc&page=${params.page}&size=${params.size}&sort=createdDate,desc`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
});
