import {
  FlatList,
  ScrollView,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import {Icon} from '@ui-kitten/components';
import {useEffect, useState} from 'react';
import {Color, Font, NavigationName} from '../../../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {styles} from './styles';
import Toast from 'react-native-toast-message';
import {t} from 'i18next';
import {useNavigation} from '@react-navigation/native';
import LoadingMore from '../../../../../../components/LoadingMore';
import TextCM from '../../../../../../components/Text';
import {useAccountInfoServices} from '../../../../../../../hooks/apiHooks/useAccountInfoServices';
import {useReceiptServices} from '../../../../../../../hooks/apiHooks/useAPI';
import {ReceiptItem} from '../../../../../../../model/interface/receipt.interface';
import {DateUtils} from '../../../../../../../utils';
import {mockData} from './helper';

type Props = {
  status: 'lated' | 'inProgress' | 'complete' | 'cancel' | 'reject' | 'draft';
};

const ListReceipt = ({status}: Props) => {
  const navigation = useNavigation();
  const ReceiptService = useReceiptServices();
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const accountService = useAccountInfoServices();
  const [typereceipt] = useState([
    {type: 'c', name: 'Biên lai C20, C21'},
    {type: 'r', name: 'Biên lai C22, C23, 03B1'},
  ]);
  const [currentTypeReceipt, setCurrentTypeReceipt] = useState<'c' | 'r'>('c');
  const [listReceipt, setListReceipt] = useState<ReceiptItem[]>([]);
  const size = 5;
  const [page, setPage] = useState(0);
  const [totalCountReceipt, setTotalCountReceipt] = useState(0);

  useEffect(() => {
    // accountService.loginMiniApp();
  }, []);

  const getDataReceipt = async (page = 0) => {
    try {
      const res = await ReceiptService.getReceipt(page, size);
      if (res?.data) {
        if (page === 0) {
          setListReceipt(res.data);
          setTotalCountReceipt(res.totalData);
        } else {
          setListReceipt(prev => [...prev, ...res.data]);
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };

  useEffect(() => {
    getDataReceipt();
  }, []);

  const onRefresh = async () => {
    try {
      setIsFreshing(true);
      await getDataReceipt();
      setPage(0);
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsFreshing(false);
    }
  };

  const navigateToDetailReceiptScreen = () => {
    navigation.navigate(NavigationName.DetailReceiptScreen as never);
  };

  const handleChangeTypeReceipt = (type: 'c' | 'r') => {
    setCurrentTypeReceipt(type);
  };

  const handleLoadMore = async () => {
    setIsLoadMore(true);
    try {
      if (listReceipt.length < totalCountReceipt) {
        await getDataReceipt(page + 1);
        setPage(page + 1);
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoadMore(false);
    }
  };

  const DashLine = () => {
    return (
      <Svg height="10" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Line
          x1="30"
          y1="5"
          x2={'93%'}
          y2="5"
          stroke="#CBCBCB"
          strokeWidth="2"
          strokeDasharray="8"
        />
      </Svg>
    );
  };

  const renderReceiptItem = (receipt: ReceiptItem) => {
    const data = receipt.data;
    return (
      <TouchableOpacity
        onPress={navigateToDetailReceiptScreen}
        style={styles.container}>
        <View
          style={[
            styles.card,
            styles.radiusTop,
            styles.shadowTop,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.header}>
            <Text style={styles.title}>{data.name}</Text>
            <Icon
              name="flag"
              width={16}
              height={16}
              fill={data.status == 'COMPLETED' ? 'green' : 'black'}
            />
          </View>

          <Text style={styles.idNumber}>{data.caseCode}</Text>
        </View>

        <DashLine />

        <View
          style={[
            styles.card,
            styles.radiusBot,
            styles.shadowBottom,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.receiptTypeSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.receiptTypeLabel}>Loại biên lai</Text>
            </View>
            <View style={{flex: 1}}>
              <Text style={styles.receiptTypeCode}>{data.type}</Text>
            </View>
          </View>

          <View style={styles.dateSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.dateLabel}>Ngày tạo</Text>
            </View>
            <Text style={styles.dateValue}>
              {DateUtils.convertDateToDDMMYYYY_H_M(data.createdDate)}
            </Text>
          </View>

          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.statusLabel}>Trạng thái Biên lai</Text>
            </View>
            <View style={[styles.statusButton, {backgroundColor: '#F2ECFD'}]}>
              <Text style={styles.statusButtonText}>{data.status}</Text>
            </View>
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  const renderTypeReceipt = (item: any) => {
    return (
      <TouchableOpacity
        key={item.type}
        onPress={() => handleChangeTypeReceipt(item.type)}
        style={styles.containerTypereceipt}>
        {currentTypeReceipt === item.type ? (
          <View style={styles.typeReceiptSelected}>
            <View
              style={{
                width: 8,
                height: 8,
                backgroundColor: Color.White,
                borderRadius: 10,
              }}></View>
          </View>
        ) : (
          <View style={styles.typeReceiptDefault}></View>
        )}
        <Text
          style={[
            styles.textTypeReceipt,
            {
              color: currentTypeReceipt === item.type ? '#262D34' : '#667085',
            },
          ]}>
          {item.name}
        </Text>
      </TouchableOpacity>
    );
  };

  return (
    <View style={{flex: 1, backgroundColor: '#f9fafe'}}>
      <View style={{flexDirection: 'row', gap: 16, marginBottom: 10}}>
        {typereceipt.map((item: any) => renderTypeReceipt(item))}
      </View>

      <FlatList
        // ref={refFlatList}
        showsVerticalScrollIndicator={false}
        style={{flex: 1}}
        data={mockData}
        keyExtractor={item => item.data.id}
        renderItem={({item}) => renderReceiptItem(item)}
        onEndReachedThreshold={0.5}
        onRefresh={onRefresh}
        refreshing={isRefreshing}
        onEndReached={handleLoadMore}
        ListEmptyComponent={() => (
          <View
            style={{
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
            }}>
            <TextCM>{t('CM.emptyData')}</TextCM>
          </View>
        )}
        ListFooterComponent={() => isLoadMore && <LoadingMore />}
      />
    </View>
  );
};

export default ListReceipt;
