import {Platform, ScrollView, Text, TouchableOpacity, View} from 'react-native';
import DocumentPicker from 'react-native-document-picker';
import HeaderCM from '../../../../components/Header/HeaderCM';
import {
  IconListtransferReceipt,
  IconMyReceiptTopRight,
  IconUploadRed,
} from '../../../../../assets/images';
import {Color} from '../../../../../constants';
import {styles} from './styles';
import {useState} from 'react';
import AttachmentItem from './component/attach-item';
import IssueReceiptItem from './component/issue-receipt-item';

interface DocumentItem {
  id: string;
  title: string;
  type?: string;
  format?: string;
  size?: string;
  step?: string;
  uploader?: {
    name: string;
    email: string;
    avatar: string;
  };
  uploadDate?: string;
  isExpanded?: boolean;
}

const Attachments = () => {
  const [attachments, setAttachments] = useState<DocumentItem[]>([
    {
      id: '1',
      title: 'Giấy báo có',
      type: 'Giấy báo có',
      format: '.png',
      size: '5MB',
      step: 'Khởi tạo biên lại',
      uploader: {
        name: 'Bùi Thị Trà My',
        email: 'MyBTT2012@gmail.com',
        avatar: 'https://api.a0.dev/assets/image?text=BTM&aspect=1:1&seed=123',
      },
      uploadDate: '20/10/2024 hh:mm',
      isExpanded: false,
    },
    {id: '2', title: 'Thông báo của toà án', isExpanded: false},
    {id: '3', title: 'Quyết định thi hành án', isExpanded: false},
    {id: '4', title: '{Tên tài liệu}', isExpanded: false},
    {id: '5', title: '{Tên tài liệu}', isExpanded: false},
  ]);
  const [proceedings] = useState<DocumentItem[]>([
    {id: '6', title: 'BLTT 156/QD - C484 - Nguyễn Văn A', isExpanded: false},
    {id: '7', title: 'TB THADS', isExpanded: false},
  ]);
  const uploadFile = async () => {
    try {
      const data = await DocumentPicker.pick({
        type: [
          DocumentPicker.types.doc,
          DocumentPicker.types.docx,
          DocumentPicker.types.xls,
          DocumentPicker.types.xlsx,
        ],
      });
      if (data) {
        const fileUri =
          Platform.OS === 'ios'
            ? data?.[0].uri.replace('file://', '')
            : data?.[0].uri;
        const file = {
          name: data[0].name,
          uri: fileUri,
          type: data[0].type,
        };
        const dataForm = new FormData();
        dataForm.append('file', file);
      }
    } catch (error) {}
  };
  return (
    <>
      <HeaderCM
        title="Biên lai phát hành & tài liệu đính kèm"
        useLinearGradient={false}
        style={{backgroundColor: Color.BgPrimary}}
        contentStyle={{backgroundColor: Color.BgPrimary}}
        renderContentRight={() => (
          <TouchableOpacity onPress={() => false}>
            <IconMyReceiptTopRight width={20} height={20} />
          </TouchableOpacity>
        )}
      />
      <View style={{backgroundColor: Color.White, flex: 1, padding: 16}}>
        <ScrollView
          style={styles.content}
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}>
          <View style={styles.sectionHeader}>
            <View style={styles.sectionTitleContainer}>
              <IconListtransferReceipt width={16} height={16} />
              <Text style={styles.sectionTitle}>Tài liệu đính kèm</Text>
            </View>
            <View></View>
            <TouchableOpacity style={styles.uploadButton} onPress={uploadFile}>
              <IconUploadRed width={10} height={10} />
              <Text style={styles.uploadText}>Tải lên</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.documentList}>
            {attachments.map((item, index) => (
              <AttachmentItem key={index} item={item} />
            ))}
          </View>

          <View style={styles.sectionHeader}>
            <View style={styles.sectionTitleContainer}>
              <IconListtransferReceipt width={16} height={16} />
              <Text style={styles.sectionTitle}>Biên lại phát hành</Text>
            </View>
          </View>

          <View style={styles.documentList}>
            {proceedings.map((item, index) => (
              <IssueReceiptItem key={index} item={item} />
            ))}
          </View>
        </ScrollView>
      </View>
    </>
  );
};

export default Attachments;
